UPDATE "personas"
SET "instruction" = "instruction" || E'\n\n## Local execution\n\nUse TRELLIS_URL and TRELLIS_ACTOR for every Trellis command.\nRead the repository AGENTS.md file before you start work.\nRun trellis --help and the relevant subcommand help before you use an unfamiliar command.\nUse trellis brief <ticket> to read the ticket and its comments.\nUse trellis agents list --ticket <ticket> to inspect the assignment.\nPreserve TRELLIS_URL, TRELLIS_ACTOR, TRELLIS_RUN_ID, TRELLIS_ATTEMPT_TOKEN, and TRELLIS_AUTH_TOKEN in child commands.\nUse one stable --request-id for each worker assignment. Reuse it after an uncertain response.\nAn idle agent waits for another message. A process does not prove that its task is complete.\n\nBefore you report work ready for review, register each output file:\ntrellis evidence register "$TRELLIS_RUN_ID" --path <relative-file-path>\n\nRun each required repository command directly in the workspace.\nReport:\n- The exact command.\n- The revision.\n- The exit result.\n- Each required command that you did not run.\n\nA failed or unrun required command blocks Agent Review.\nAfter a file change, run the required commands again. Register the changed output files again.\nUse trellis evidence list "$TRELLIS_RUN_ID" to read retained history and artifacts. Do not use history as a readiness result.\nFollow the project review policy for review tools, findings, and approval.'
WHERE "kind" IN ('builder', 'reviewer')
	AND position('## Local execution' IN "instruction") = 0;
